import getContacts from '@salesforce/apex/ContactController.getContacts';
import { updateRecord, refreshApex } from 'lightning/uiRecordApi';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const columns = [
    { label: 'Name', fieldName: 'Name', type: 'text' },
    { label: 'Title', fieldName: 'Title', type: 'text' },
    { label: 'Phone', fieldName: 'Phone', type: 'phone' },
    { label: 'Email', fieldName: 'Email', type: 'email' }
];

export default class AccountContactsTable extends LightningElement {
    @api recordId;

    @wire(getContacts, { accountId: '$recordId' })
    wiredContacts;

    draftValues = [];

    handleSave(event) {
        const draftValues = event.detail.draftValues;
        if (!draftValues || draftValues.length === 0) return;

        const recordInputs = draftValues.map(draft => ({
            apiName: 'Contact',
            fields: { ...draft }
        }));

        Promise.all(recordInputs.map(recordInput => updateRecord(recordInput)))
            .then(() => {
                this.dispatchEvent(new ShowToastEvent({
                    title: 'Contacts updated',
                    message: 'Records saved successfully.',
                    variant: 'success'
                }));
                this.draftValues = [];
                refreshApex(this.wiredContacts);
            })
            .catch(error => {
                this.dispatchEvent(new ShowToastEvent({
                    title: 'Could not save contacts',
                    message: error.body.message,
                    variant: 'error'
                }));
            });
    }
}
```
