/**
 * Service class to manage contact current employers using NPSP Affiliations.
 * Leverages NPSP's standard trigger behavior to automatically update
 * primary lookups and demote previous primary employers to Former status.
 */
public class EmployerService {

    /**
     * Sets the current primary employer for a list of contacts.
     *
     * @param employerByContactId Map of Contact Id to Organization Account Id
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Query existing primary, current affiliations for the specified contacts
        // Uses 1 SOQL query
        List<npe01__Affiliation__c> existingPrimaryAffiliations = [
            SELECT Id, npe01__Contact__c, npe01__Account__c
            FROM npe01__Affiliation__c
            WHERE npe01__Contact__c IN :employerByContactId.keySet()
              AND npe01__IsPrimary__c = true
              AND npe01__Status__c = 'Current'
        ];

        // Build a lookup map for existing primary employer (ContactId -> AccountId)
        Map<Id, Id> contactIdToExistingPrimaryOrgId = new Map<Id, Id>();
        for (npe01__Affiliation__c aff : existingPrimaryAffiliations) {
            contactIdToExistingPrimaryOrgId.put(aff.npe01__Contact__c, aff.npe01__Account__c);
        }

        List<npe01__Affiliation__c> affiliationsToInsert = new List<npe01__Affiliation__c>();

        // Iterate through the input map and build new affiliations
        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);

            // Skip if account ID is null
            if (orgId == null) {
                continue;
            }

            // Skip if this org is already the primary employer to prevent duplicates
            if (contactIdToExistingPrimaryOrgId.containsKey(contactId) &&
                contactIdToExistingPrimaryOrgId.get(contactId) == orgId) {
                continue;
            }

            npe01__Affiliation__c newAffiliation = new npe01__Affiliation__c(
                npe01__Contact__c = contactId,
                npe01__Account__c = orgId,
                npe01__IsPrimary__c = true,
                npe01__Status__c = 'Current'
            );
            affiliationsToInsert.add(newAffiliation);
        }

        // Insert new affiliations. NPSP triggers will automatically handle:
        // 1. Updating Contact.PrimaryAffiliation__c to the new affiliation
        // 2. Demoting the previous primary affiliation to 'Former' with EndDate = Today
        // 3. Maintaining household account linkage
        // Uses 1 DML statement
        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
        }
    }
}
```

