        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();
        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];
            npsp__DataImport__c importRecord = new npsp__DataImport__c();

            // Map web gift fields to NPSP Data Import record structure
            importRecord.npsp__Primary__c = gift.email;
            importRecord.npsp__PrimaryType__c = 'Contact';
            importRecord.npsp__Type__c = 'Opportunity';
            importRecord.npsp__Amount__c = gift.amount;
            importRecord.npsp__Date__c = gift.giftDate;
            importRecord.npsp__Secondary__c = gift.firstName + ' ' + gift.lastName;

            dataImports.add(importRecord);
        }

        // Process synchronously in the same transaction using NPSP's Apex API
        List<DataImportService.ImportResult> npspResults = DataImportService.importData(dataImports);

        // Map NPSP results back to our wrapper in original input order
        List<ImportResult> results = new List<ImportResult>();
        for (Integer i = 0; i < npspResults.size(); i++) {
            DataImportService.ImportResult npspRes = npspResults[i];
            ImportResult res = new ImportResult();
            res.success = npspRes.success;
            res.contactId = npspRes.contactId;
            res.opportunityId = npspRes.opportunityId;
            res.errorMessage = npspRes.errorMessage;
            results.add(res);
        }

        return results;
    }
}
