    public static void afterInsert() { run(); }
    public static void afterUpdate() { run(); }
    public static void afterDelete() { run(); }
    public static void afterUndelete() { run(); }

    private static void run() {
        Set<Id> accountIds = new Set<Id>();

        if (Trigger.isAfter) {
            if (Trigger.isInsert || Trigger.isUndelete) {
                for (Case c : Trigger.New) {
                    if (c.AccountId != null) {
                        accountIds.add(c.AccountId);
                    }
                }
            } else if (Trigger.isUpdate) {
                for (Case c : Trigger.New) {
                    if (c.AccountId != null) {
                        accountIds.add(c.AccountId);
                    }
                }
                for (Case c : Trigger.Old) {
                    if (c.AccountId != null && c.AccountId != Trigger.NewMap.get(c.Id).AccountId) {
                        accountIds.add(c.AccountId);
                    }
                }
            } else if (Trigger.isDelete) {
                for (Case c : Trigger.Old) {
                    if (c.AccountId != null) {
                        accountIds.add(c.AccountId);
                    }
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> openCaseCounts = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId aId, COUNT(Id) cnt 
            FROM Case 
            WHERE AccountId IN :accountIds 
            AND IsClosed = false 
            GROUP BY AccountId
        ]) {
            openCaseCounts.put((Id)ar.get('aId'), (Integer)ar.get('cnt'));
        }

