public class TA_Contact_InheritMailingAddress {
    public static void execute(List<SObject> records) {
        List<Contact> contacts = (List<Contact>) records;
        TA_Contact_Queries queries = TA_Contact_Queries.getInstance();

        if (queries.accountsById == null || queries.accountsById.isEmpty()) return;

        for (Contact c : contacts) {
            if (c.AccountId != null) {
                Account acc = queries.accountsById.get(c.AccountId);
                if (acc != null) {
                    // Only copy if all four mailing fields are blank
                    if (c.MailingStreet == null && c.MailingCity == null && 
                        c.MailingPostalCode == null && c.MailingCountry == null) {
                        c.MailingStreet = acc.BillingStreet;
                        c.MailingCity = acc.BillingCity;
                        c.MailingPostalCode = acc.BillingPostalCode;
                        c.MailingCountry = acc.BillingCountry;
                    }
                }
            }
        }
    }
}
